 1→resource "google_compute_security_policy" "cloud_armor_policy" {
 2→  name        = var.policy_name
 3→  description = var.policy_description
 4→}
 5→
 6→resource "google_compute_security_policy_rule" "rules" {
 7→  for_each        = var.rules
 8→  security_policy = google_compute_security_policy.cloud_armor_policy.name
 9→  priority        = tonumber(each.key)
10→  action          = each.value.action
11→  preview         = each.value.preview
12→  description     = each.value.description
13→
14→  match {
15→    versioned_expr = lookup(each.value, "versioned_expr", null)
16→
17→    dynamic "config" {
18→      for_each = (
19→        contains(keys(each.value), "versioned_expr") &&
20→        each.value.versioned_expr != "" &&
21→        contains(keys(each.value), "src_ip_ranges") &&
22→        try(length(each.value.src_ip_ranges), 0) > 0
23→      ) ? [1] : []
24→      content {
25→        src_ip_ranges = each.value.src_ip_ranges
26→      }
27→    }
28→
29→    dynamic "expr" {
30→      for_each = each.value.expr != null && each.value.expr != "" ? [1] : []
31→      content {
32→        expression = each.value.expr
33→      }
34→    }
35→  }
36→
37→  dynamic "rate_limit_options" {
38→    for_each = (
39→      can(each.value.rate_limit_options) &&
40→      contains(["rate_based_ban", "throttle", "fairshare"], lower(each.value.action))
41→    ) ? [1] : []
42→    content {
43→      conform_action = "allow"
44→      exceed_action  = "deny(429)"
45→      enforce_on_key = "IP"
46→
47→      rate_limit_threshold {
48→        count        = each.value.rate_limit_options.rate_limit_threshold.count
49→        interval_sec = each.value.rate_limit_options.rate_limit_threshold.interval_sec
50→      }
51→
52→      dynamic "ban_threshold" {
53→        for_each = try(each.value.rate_limit_options.ban_threshold != null, false) ? [1] : []
54→        content {
55→          count        = each.value.rate_limit_options.ban_threshold.count
56→          interval_sec = each.value.rate_limit_options.ban_threshold.interval_sec
57→        }
58→      }
59→
60→      ban_duration_sec = try(each.value.rate_limit_options.ban_duration_sec, null)
61→    }
62→  }
63→
64→  lifecycle {
65→    ignore_changes = [
66→      rate_limit_options
67→    ]
68→  }
69→}
70→
71→

 1→variable "policy_name" {
 2→  type        = string
 3→  description = "Nombre de la política de Cloud Armor"
 4→}
 5→
 6→variable "policy_description" {
 7→  type        = string
 8→  description = "Descripción de la política"
 9→}
10→
11→variable "rules" {
12→  description = "Mapa de reglas para el WAF"
13→  type = map(object({
14→    action         = string
15→    preview        = optional(bool, false)
16→    description    = optional(string)
17→    versioned_expr = optional(string)
18→    src_ip_ranges  = optional(list(string))
19→    expr           = optional(string)
20→    rate_limit_options = optional(object({
21→      rate_limit_threshold = object({
22→        count        = number
23→        interval_sec = number
24→      })
25→      ban_threshold = optional(object({
26→        count        = number
27→        interval_sec = number
28→      }))
29→      ban_duration_sec = optional(number)
30→    }))
31→  }))
32→}
33→

